import type { ReactNode } from 'react'
import { DuoGlyph, type GlyphProps } from './duo-glyph'
import { glyphSvgProps } from './glyph-svg-props'

// 垫淡填充的那层：颜色和浓淡由调用处的 CSS 变量决定，好让导航、轨道头按媒体种类着色
const FILL = 'final-cut-glyph-fill'
// 细线：刻度、副线这类不该和主描边抢的笔画
const THIN = 1.4

const glyph = (body: ReactNode) =>
  function FinalCutGlyph(props: GlyphProps) {
    return <DuoGlyph {...props}>{body}</DuoGlyph>
  }

/**
 * 按设计稿描摹的图标：墨线层 `ink` 是实心填充路径（当前文字色），不描边，描边会把它描粗；`fill` 是垫在下面的
 * 淡填充层（颜色和浓淡同 `FILL`：导航、轨道头由调用处换成媒体种类色，通用操作跟线条同色）。
 */
const traced = (ink: string, fill?: string) =>
  function FinalCutTracedGlyph(props: GlyphProps) {
    return (
      <svg {...glyphSvgProps(props)}>
        {fill === undefined ? null : <path className={FILL} d={fill} />}
        <path d={ink} fill="currentColor" />
      </svg>
    )
  }

